action.command:
cd /workspace && timeout 280 pnpm env:doctor:local-builder --json 2>/dev/null > /tmp/doctor.json; echo "raw_exit:$?"; python3 -c "
import json
d=json.load(open('/tmp/doctor.json'))
checks = d if isinstance(d,list) else d.get('checks') or d.get('results') or []
if not checks and isinstance(d,dict):
    print('TOP KEYS:', list(d.keys()))
for c in checks:
    if isinstance(c,dict) and c.get('status') in ('error','warn','skipped'):
        print(f\"{c.get('status'):8} | {c.get('code') or c.get('name'):55} | {str(c.get('message'))[:120]}\")
"

